function Checkout({ items }) {
  function formatPrice(cents) {
    return '$' + (cents / 100).toFixed(2)
  }

  return (
    <ul>
      {items.map((item) => (
        <li key={item.id}>{item.name} {formatPrice(item.cents)}</li>
      ))}
    </ul>
  )
}

